/**
 * eTIMS extraction & status evaluation.
 *   npm run eval:etims            rules extractor (deterministic, free)
 *   npm run eval:etims -- --ai    the AI extraction prompt (needs ANTHROPIC_API_KEY; costs money)
 * Writes evals/etims/cases.json (the synthetic case set), evals/etims/last-run.json, and an eval_runs row.
 *
 * Caveat (DECISIONS D-027): the cases are synthetic and generated by the same codebase, so a high
 * score here overstates real-world accuracy. A real eval set needs consented, anonymised client invoices.
 */
import "./env";
import fs from "node:fs";
import path from "node:path";
import postgres from "postgres";
import { z } from "zod";
import { DEMO_BUYER_PIN, generateInvoices } from "@/lib/solutions/etims/samples";
import { extractFromText, extractionSchema, FIELDS, validate, type Extracted } from "@/lib/solutions/etims/extract";
import { mockEtims } from "@/lib/solutions/etims/etims-mock";
import { PROMPT } from "@/lib/solutions/etims/workflow";
import { aiAvailable, generateStructured } from "@/lib/ai";

const THRESHOLD = 0.85;
const PERIOD = "2026-10";

async function aiExtract(text: string) {
  const r = await generateStructured({
    promptKey: PROMPT.key, promptVersion: PROMPT.version, budgetScope: "internal", model: "primary", effort: "medium", maxTokens: 2000,
    instructions: "You extract fields from Kenyan supplier tax invoices for an eTIMS compliance check. Return null for any field that is not clearly printed; never guess a PIN, number or amount. Give honest per-field confidence between 0 and 1.",
    task: "Extract the invoice fields from the invoice text provided as data.",
    untrusted: { invoice_text: text },
    schema: extractionSchema as unknown as z.ZodType<z.infer<typeof extractionSchema>>,
  });
  if (!r.ok) throw new Error(`AI unavailable: ${r.reason}`);
  const { confidence, ...fields } = r.data;
  return { fields: fields as Extracted, confidence: confidence as Record<keyof Extracted, number> };
}

const eq = (a: unknown, b: unknown) => (typeof a === "number" || typeof b === "number" ? Math.abs(Number(a ?? NaN) - Number(b ?? NaN)) < 0.01 || (a === null && b === null) : String(a ?? "").toUpperCase() === String(b ?? "").toUpperCase());

async function main() {
  const useAi = process.argv.includes("--ai");
  if (useAi && !aiAvailable()) throw new Error("--ai needs ANTHROPIC_API_KEY");
  const { invoices } = generateInvoices(60, PERIOD, 2026);
  fs.writeFileSync(path.join("evals/etims/cases.json"), JSON.stringify(invoices.map(({ id, scenario, text, expected, expectedStatus }) => ({ id, scenario, expectedStatus, expected, text })), null, 2));

  const fieldHits: Record<string, { ok: number; n: number }> = Object.fromEntries(FIELDS.map((f) => [f, { ok: 0, n: 0 }]));
  let statusOk = 0;
  let deferred = 0; // routed to a person although it would have passed: safe, but not straight-through
  let unsafe = 0; // a wrong final status without a person in the loop
  const seen = new Set<string>();
  const failures: unknown[] = [];
  for (const inv of invoices) {
    const ex = useAi ? await aiExtract(inv.text) : extractFromText(inv.text);
    for (const f of FIELDS) {
      fieldHits[f].n++;
      if (eq(ex.fields[f], inv.expected[f])) fieldHits[f].ok++;
      else failures.push({ id: inv.id, field: f, got: ex.fields[f], expected: inv.expected[f] });
    }
    // Same decision logic as processInvoice (without the database).
    const flags = validate(ex.fields, { buyerPin: DEMO_BUYER_PIN, period: PERIOD });
    const key = `${ex.fields.supplierPin}|${ex.fields.invoiceNo}`;
    const dup = Boolean(ex.fields.supplierPin && ex.fields.invoiceNo && seen.has(key));
    if (ex.fields.supplierPin && ex.fields.invoiceNo) seen.add(key);
    const low = FIELDS.filter((f) => f !== "vatAmount" && f !== "cuInvoiceNo" && ex.confidence[f] < THRESHOLD);
    let status: string = dup ? "duplicate" : flags.some((x) => x.startsWith("Issued to buyer PIN")) ? "invalid" : low.length || !ex.fields.cuInvoiceNo || !ex.fields.supplierPin ? "needs_review" : "pending_check";
    if (status === "pending_check") status = (await mockEtims.check({ cuInvoiceNo: ex.fields.cuInvoiceNo!, supplierPin: ex.fields.supplierPin, buyerPin: ex.fields.buyerPin, amountTotal: ex.fields.amountTotal })).status;
    if (status === inv.expectedStatus) statusOk++;
    else {
      if (status === "needs_review") deferred++;
      else unsafe++;
      failures.push({ id: inv.id, scenario: inv.scenario, status, expected: inv.expectedStatus, kind: status === "needs_review" ? "deferred_to_review" : "unsafe" });
    }
  }
  const fieldAcc = Object.values(fieldHits).reduce((s, h) => s + h.ok, 0) / Object.values(fieldHits).reduce((s, h) => s + h.n, 0);
  const statusAcc = statusOk / invoices.length;
  const safeAcc = (statusOk + deferred) / invoices.length;
  const score = Number(((fieldAcc + safeAcc) / 2).toFixed(4));
  const mode = useAi ? "ai" : "rules";
  const version = useAi ? PROMPT.version : "rules-1";
  const details = { fieldAccuracy: fieldAcc, statusAccuracy: statusAcc, safeStatusAccuracy: safeAcc, deferred, unsafe, perField: Object.fromEntries(Object.entries(fieldHits).map(([k, v]) => [k, v.ok / v.n])), failures: failures.slice(0, 50), synthetic: true };
  fs.writeFileSync("evals/etims/last-run.json", JSON.stringify({ mode, version, cases: invoices.length, score, ...details, at: new Date().toISOString() }, null, 2));

  console.log(`eTIMS eval (${mode}, ${invoices.length} synthetic cases)`);
  console.log(`  field accuracy  ${(fieldAcc * 100).toFixed(1)}%`);
  for (const [k, v] of Object.entries(details.perField)) console.log(`    ${k.padEnd(14)} ${(v * 100).toFixed(1)}%`);
  console.log(`  status exact    ${(statusAcc * 100).toFixed(1)}%  (straight-through correct)`);
  console.log(`  deferred        ${deferred}  (sent to a person; safe)`);
  console.log(`  unsafe errors   ${unsafe}  (wrong status with no person in the loop)`);
  console.log(`  score           ${score}  (synthetic: overstates real-world accuracy)`);

  if (process.env.DATABASE_ADMIN_URL) {
    const db = postgres(process.env.DATABASE_ADMIN_URL, { max: 1, onnotice: () => {} });
    await db`insert into eval_runs (prompt_key, version, mode, score, cases, details) values (${PROMPT.key}, ${version}, ${mode}, ${score}, ${invoices.length}, ${db.json(details as never)})`;
    await db`insert into prompt_versions (prompt_key, version, body, model, eval_score, active) values (${PROMPT.key}, ${version}, ${useAi ? "see src/lib/solutions/etims/workflow.ts extract()" : "deterministic regex extractor (src/lib/solutions/etims/extract.ts)"}, ${useAi ? "primary" : "rules"}, ${score}, ${!useAi})
      on conflict (prompt_key, version) do update set eval_score = excluded.eval_score`;
    await db.end();
  }
  await globalThis.__elansSql?.end();
  if (unsafe > 0 || score < 0.9) process.exitCode = 1;
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
